 *
 * @author <NAME>
 */
public enum FXMLPage implements PageType {

    StandaloneFxml,
    IncludedFxml,
    ViewEmbeddedFxml,
    HybridFxml;

    /**
     * {@inheritDoc}
     */
    @Override
    public UniqueIdentifier<? extends Model> getModelKey() {
        switch (this) {
            default:
            case ViewEmbeddedFxml:
                return Key.create(EmbeddedModel.class);
            case StandaloneFxml:
                return Key.create(StandaloneModel.class);
            case HybridFxml:
                return Key.create(HybridModel.class, FXMLModel.KEYPART_FXML_PREFIX + "org.jrebirth.af.showcase.fxml.ui.hybrid.Hybrid");
            case IncludedFxml:
                return Key.create(IncludedModel.class, new LoremText());
        }
    }

}

