@ActiveProfiles("default")
public class RetryExam {
    @Configuration
    @ImportAutoConfiguration({
          JacksonAutoConfiguration.class,
          LogbookAutoConfiguration.class,
          OpenTracingTestAutoConfiguration.class,
          MetricsTestAutoConfiguration.class,
    })
    static class ContextConfiguration {
    }

    @Autowired
    @Qualifier("retry-exam")
    private Http retryClient;

    @Autowired
    private MockRestServiceServer server;

    @Test
    void shouldRetryForAt MostMaximumRetriesTimes() {
        server.expect(times(3), requestTo("http://retry-exam")).andRespond(withServerError());

        assertThrows(CompletionException.class,
              () -> retryClient.get().dispatch(series(), on(SERVER_ERROR).call(retry())).join());

        server.verify();
    }
}

