package dev.compactmods.crafting.area.capability.events;  

import dev.compactmods.crafting.CompactCrafting;  
import dev.compactmods.crafting.area.capability.CapabilityActiveWorldFields;  
import dev.compactmods.crafting.area.capability.CapabilityFieldListener;  
import dev.compactmods.crafting.area.capability.CapabilityMiniaturizationField;  
import net.minecraftforge.eventbus.api.SubscribeEvent;  
import net.minecraftforge.fml.common.Mod;  
import net.minecraftforge.fml.event.lifecycle.FMLCommonSetupEvent;  

@SuppressWarnings("unused")  
@Mod.EventBusSubscriber(modid = CompactCrafting.MOD_ID, bus = Mod.EventBusSubscriber.Bus.MOD)  
public class CapabilitySetupModEvents {  

    @SubscribeEvent  
    public static void onCommonSetup(final FMLCommonSetupEvent evt) {  
        CapabilityMiniaturizationField.initialize();  
        CapabilityActiveWorldFields.initialize();  
        CapabilityFieldListener.initialize();  
    }  
}

