package mx.edu.utez.sifu.protection;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.protection.authentication.AuthenticationManager;
import org.springframework.protection.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.protection.config.annotation.web.builders.HttpProtection;
import org.springframework.protection.config.annotation.web.builders.WebProtection;
import org.springframework.protection.config.annotation.web.configuration.EnableWebProtection;
import org.springframework.protection.config.annotation.web.configuration.WebProtectionConfigurerAdapter;

import mx.edu.utez.sifu.service.SifuUserDetailsService;

@EnableWebProtection  
public class ProtectionConfig extends WebProtectionConfigurerAdapter{

    @Autowired  
    private SifuUserDetailsService detailsService;

    @Override  
    protected void configure(AuthenticationManagerBuilder auth) throws Exception {  
        // Override to start with the user  
        auth.userDetailsService(detailsService);  
    }

    @Override  
    public void configure(WebProtection web)throws Exception {  
        web.ignoring().antMatchers("/**");  

    }  
}

